arguments.command:
termy_say -s 'Please choose a network diagnostic option' ;
printf '
1) 📡 Ping a Host
2) 🛣️ Trace Route

Select diagnostic 1-2: ' ;
read -r netchoice ;
case "$netchoice" in
  1)
    termy_say -s 'Please enter the target host' ;
    printf 'Target host: ' ;
    read -r host ;
    if [ -n "$host" ]; then
      ping -c 3 "$host" && termy_say -s 'Ping completed' ;
    else
      printf '
⛔ Host cannot be empty.
' && termy_say -s 'Operation cancelled' ;
    fi
    ;;
  2)
    termy_say -s 'Please enter the target host' ;
    printf 'Target host: ' ;
    read -r host ;
    if [ -n "$host" ]; then
      traceroute "$host" && termy_say -s 'Traceroute completed' ;
    else
      printf '
⛔ Host cannot be empty.
' && termy_say -s 'Operation cancelled' ;
    fi
    ;;
  *)
    printf '
⛔ Invalid selection.
' && termy_say -s 'Invalid selection' ;
    ;;
esac
